// editorial/emails/newsletter.tsx, from hyperelements.dev/templates. Replace the brand block with your own brand.

import { Button, Column, Divider, Email, Heading, Image, Link, Row, Text, defineTheme, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Orbit",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#0b1020",
      primary: "#4f46e5",
      primaryForeground: "#ffffff",
      border: "#e2e5ee",
      muted: "#5b6478",
      surface: "#f4f5fa",
      accent: "#2dd4bf",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "Inter, 'Helvetica Neue', Arial, sans-serif" },
    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 40 },
    radii: { sm: 6, md: 12 },
    elements: {
      Heading: {
        fontWeight: 700,
        by: {
          level: {
            1: { fontSize: 32, lineHeight: 1.15 },
            2: { fontSize: 24, lineHeight: 1.25 },
            3: { fontSize: 19, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/orbit/logo.png", width: 480, height: 120, alt: "Orbit" },
  address: "1 Main Street, Springfield",
  links: { site: "https://orbit.example", domains: ["orbit.example", "*.orbit.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
  ],
};
// brand: end

// The design
const meta = {
  label: "Newsletter",
  description: "A regular issue: a masthead with the issue and date, a lead story, more stories with thumbnails, a closing note, and an unsubscribe footer",
};

function EditorialNewsletter() {
  return (
    <Email
      width={600}
      title="What's new this month"
      previewText="Faster exports, notes in your own voice, and a date for the open house"
      lang={brand.lang ?? "en"}
      dir={brand.dir}
      theme={brand.theme}
      fonts={brand.fonts}
      style={{
        backgroundColor: token("colors.surface"),
        fontSize: token("fontSizes.body"),
        lineHeight: token("lineHeights.body"),
      }}
    >
      <Column style={{ padding: [token("spacing.lg"), token("spacing.md")], gap: token("spacing.lg") }}>
        <Row
          stackOnMobile={false}
          style={{ alignItems: "center", gap: token("spacing.md"), padding: [0, token("spacing.sm")] }}
        >
          <Column>
            <Image
              src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }}
              alt={brand.logo.alt}
              style={{ width: 140 }}
            />
          </Column>
          <Column>
            <Text
              style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "right" }}
            >
              No. 14 · March 5
            </Text>
          </Column>
        </Row>
        <Column
          style={{
            backgroundColor: token("colors.background"),
            borderRadius: token("radii.md"),
            border: { width: 1, style: "solid", color: token("colors.border") },
          }}
        >
          <Column style={{ padding: token("spacing.xl"), gap: token("spacing.md") }}>
            <Text
              style={{
                fontSize: token("fontSizes.small"),
                fontWeight: 700,
                letterSpacing: 1.5,
                textTransform: "uppercase",
                color: token("colors.primary"),
              }}
            >
              This month
            </Text>
            <Heading level={1}>Exports that finish before your coffee does</Heading>
            <Text>
              We rebuilt the export pipeline from the ground up. Big projects that took minutes now take seconds, and there's nothing to change in your settings to get it.
            </Text>
            <Button
              href={`${brand.links.site}/blog/faster-exports`}
              style={{ borderRadius: token("radii.sm"), padding: [token("spacing.sm"), token("spacing.lg")] }}
            >
              Read about faster exports
            </Button>
          </Column>
          <Column style={{ padding: [0, token("spacing.xl"), token("spacing.xl")], gap: token("spacing.lg") }}>
            <Divider />
            <Heading level={2}>Also in this issue</Heading>
            <Row style={{ gap: token("spacing.md"), alignItems: "start" }}>
              <Column style={{ width: 140 }}>
                <Image
                  src={{
                    src: "https://hyperelements.dev/generated/kits/assets/kits/editorial/recorder.png",
                    width: 1020,
                    height: 900,
                  }}
                  alt=""
                  style={{ width: 140, borderRadius: token("radii.sm") }}
                />
              </Column>
              <Column style={{ gap: token("spacing.xs") }}>
                <Heading level={3}>
                  <Link href={`${brand.links.site}/blog/your-voice`} style={{ textDecoration: "none" }}>
                    Notes that sound like you
                  </Link>
                </Heading>
                <Text style={{ color: token("colors.muted") }}>
                  Release notes now start from what you've written before, so a first draft already has your voice.
                </Text>
              </Column>
            </Row>
            <Row style={{ gap: token("spacing.md"), alignItems: "start" }}>
              <Column style={{ width: 140 }}>
                <Image
                  src={{
                    src: "https://hyperelements.dev/generated/kits/assets/kits/editorial/shapes.png",
                    width: 1600,
                    height: 1200,
                  }}
                  alt=""
                  style={{ width: 140, borderRadius: token("radii.sm") }}
                />
              </Column>
              <Column style={{ gap: token("spacing.xs") }}>
                <Heading level={3}>
                  <Link href={`${brand.links.site}/blog/shared-boards`} style={{ textDecoration: "none" }}>
                    A new look for shared boards
                  </Link>
                </Heading>
                <Text style={{ color: token("colors.muted") }}>
                  Boards you share outside your team get cleaner cards and a calmer layout.
                </Text>
              </Column>
            </Row>
            <Row style={{ gap: token("spacing.md"), alignItems: "start" }}>
