import { Button, Column, Divider, Email, Heading, Image, Link, Text, defineTheme, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Pell & Ashby",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#1c1b19",
      primary: "#24513d",
      primaryForeground: "#ffffff",
      border: "#dad6cd",
      muted: "#66625a",
      surface: "#f6f4ef",
      accent: "#b9c7bc",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'Source Serif 4', Georgia, 'Times New Roman', serif" },
    fontSizes: { body: 15, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 12, lg: 20, xl: 32 },
    radii: { sm: 0, md: 0 },
    elements: {
      Heading: {
        fontWeight: 600,
        by: {
          level: {
            1: { fontSize: 30, lineHeight: 1.15 },
            2: { fontSize: 22, lineHeight: 1.25 },
            3: { fontSize: 18, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/pell-ashby/logo.png", width: 480, height: 120, alt: "Pell & Ashby" },
  address: "3 Lincoln's Court, Philadelphia",
  links: { site: "https://pellashby.example", domains: ["pellashby.example", "*.pellashby.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "Source Serif 4", src: "https://hyperelements.dev/generated/kits/assets/fonts/SourceSerif4-600.ttf", weight: 600, style: "normal" },
  ],
};
// brand: end

// The design
const meta = {
  label: "Magic link",
  description: "A one-time link that signs the reader in, how long it works, and a note for when they didn't ask",
};

function MinimalMagicLink() {
  return (
    <Email
      width={560}
      title={`Sign in to ${brand.name}`}
      previewText="Your sign-in link works for 15 minutes."
      lang={brand.lang ?? "en"}
      dir={brand.dir}
      theme={brand.theme}
      fonts={brand.fonts}
      style={{
        backgroundColor: token("colors.surface"),
        fontSize: token("fontSizes.body"),
        lineHeight: token("lineHeights.body"),
      }}
    >
      <Column
        style={{
          padding: [token("spacing.xl"), token("spacing.md"), token("spacing.lg")],
          gap: token("spacing.lg"),
        }}
      >
        <Column style={{ alignItems: "center" }}>
          <Image
            src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }}
            alt={brand.logo.alt}
            style={{ width: 150 }}
          />
        </Column>
        <Column
          style={{
            backgroundColor: token("colors.background"),
            borderRadius: token("radii.md"),
            border: { width: 1, style: "solid", color: token("colors.border") },
          }}
        >
          <Column style={{ padding: token("spacing.xl"), gap: token("spacing.md") }}>
            <Column style={{ gap: token("spacing.md"), alignItems: "center", textAlign: "center" }}>
              <Text
                style={{
                  fontSize: token("fontSizes.small"),
                  fontWeight: 700,
                  letterSpacing: 1.5,
                  textTransform: "uppercase",
                  color: token("colors.primary"),
                }}
              >
                Sign in
              </Text>
              <Heading level={1}>Sign in to {brand.name}</Heading>
              <Text>Use this link on the device where you asked for it. No password needed.</Text>
              <Button
                href={`${brand.links.site}/login/3be8f1`}
                style={{ borderRadius: token("radii.sm"), padding: [token("spacing.sm"), token("spacing.xl")] }}
              >
                Sign in to {brand.name}
              </Button>
              <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted") }}>
                It works once, for the next 15 minutes.
              </Text>
              <Divider />
              <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted") }}>
                Didn't ask to sign in? Someone may have typed your address by mistake. Nobody can get in without this link.
              </Text>
            </Column>
          </Column>
        </Column>
        <Column style={{ gap: token("spacing.xs") }}>
          <Text
            style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "center" }}
          >
            {brand.name} · {brand.address}
          </Text>
          <Text
            style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "center" }}
          >
            <Link href={`${brand.links.site}/`}>Visit {brand.name}</Link>
            {" · "}
            <Link href={`${brand.links.site}/help`}>Get help from {brand.name}</Link>
          </Text>
        </Column>
      </Column>
    </Email>
  );
}

export default MinimalMagicLink;

